begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.is_current_auth_session_active()','execute'),'anonymous cannot inspect sessions');
select ok(has_function_privilege('authenticated','public.is_current_auth_session_active()','execute'),'authenticated can inspect only signed own session');
insert into auth.users(id,email_confirmed_at) values('a6500000-0000-0000-0000-000000000001',now()),('a6500000-0000-0000-0000-000000000002',now()),('a6500000-0000-0000-0000-000000000003',null);
insert into auth.sessions(id,user_id,not_after) values('a6520000-0000-0000-0000-000000000001','a6500000-0000-0000-0000-000000000001',null),('a6520000-0000-0000-0000-000000000002','a6500000-0000-0000-0000-000000000002',null),('a6520000-0000-0000-0000-000000000003','a6500000-0000-0000-0000-000000000001',now()-interval '1 minute'),('a6520000-0000-0000-0000-000000000004','a6500000-0000-0000-0000-000000000003',null);
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001","session_id":"a6520000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select ok(public.is_current_auth_session_active(),'verified own retained session is active');
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001","session_id":"a6520000-0000-0000-0000-000000000002"}',true);
select ok(not public.is_current_auth_session_active(),'foreign session claim denied');
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001","session_id":"a6520000-0000-0000-0000-000000000003"}',true);
select ok(not public.is_current_auth_session_active(),'expired Auth session denied');
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000003","session_id":"a6520000-0000-0000-0000-000000000004"}',true);
select ok(not public.is_current_auth_session_active(),'unconfirmed identity denied');
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001"}',true);
select ok(not public.is_current_auth_session_active(),'missing signed session denied');
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001","session_id":"invalid"}',true);
select ok(not public.is_current_auth_session_active(),'malformed signed session denied');
reset role;
delete from auth.sessions where id='a6520000-0000-0000-0000-000000000001';
select set_config('request.jwt.claims','{"sub":"a6500000-0000-0000-0000-000000000001","session_id":"a6520000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select ok(not public.is_current_auth_session_active(),'deleted session JWT does not regain developer access');
select throws_ok($$select * from auth.sessions$$,'42501',null,'browser role cannot inspect raw sessions');
select throws_ok($$select * from private.parent_student_previews$$,'42501',null,'browser role cannot rewrite preview state');
select ok(not has_table_privilege('authenticated','public.student_skills','update'),'developer predicate does not grant learning mutation');
select ok(not has_table_privilege('authenticated','public.lesson_schedules','update'),'developer predicate does not grant schedule mutation');
select * from finish();
rollback;
